INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 1000, "vo_minigame_1013_icon_2_002_001", 3000, 2, "訓練はまだ\nここからですわ", "調子が上がって\nきたなっ", 1, "vo_minigame_1013_icon_1_002_001", 2);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 5000, "vo_minigame_1013_icon_2_003_001", 3000, 2, "クスクス、悪くない\n流れですわね", "ほらほら、\nまだいけるだろ？", 2, "vo_minigame_1013_icon_1_003_001", 2);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 10000, "vo_minigame_1013_icon_2_004_001", 3000, 2, "すばらしい\n記録ですわ", "へへっ、おまえら\nやるじゃねえか！", 3, "vo_minigame_1013_icon_1_004_001", 3);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 10000, "vo_minigame_1013_icon_2_005_001", 3000, 2, "乗りに乗って\nいますわね", "あたしたちはまだ\n止まらねえぜ！", 4, "vo_minigame_1013_icon_1_005_001", 3);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 10000, "vo_minigame_1013_icon_2_005_002", 3000, 2, "まだまだ行きます\nついてきなさい", "見てろよ！\nマコト班の快進撃だ！", 5, "vo_minigame_1013_icon_1_005_002", 3);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 10000, "vo_minigame_1013_icon_2_005_003", 3000, 2, "エリコ班の\n本領発揮ですわ！", "うおぉぉっ！\n絶好調だぜ！", 6, "vo_minigame_1013_icon_1_005_003", 3);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (4, 0, "vo_minigame_1013_icon_2_006_001", 3000, 2, "ここからは\n前人未到の領域です！", "どこまで行けるか\n楽しみだなっ！", 7, "vo_minigame_1013_icon_1_006_001", 3);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, 1, "vo_minigame_1013_icon_2_007_001", 1000, 3, "厄介でしたわ…", "まだ諦めんなよっ", 8, "vo_minigame_1013_icon_1_007_001", 4);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, 1, "vo_minigame_1013_icon_2_007_002", 1000, 3, "油断大敵です", "冷やっとしたぜ…！", 9, "vo_minigame_1013_icon_1_007_002", 4);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, 1, "vo_minigame_1013_icon_2_007_003", 1000, 3, "忌々しいっ…", "弱音を吐くなっ", 10, "vo_minigame_1013_icon_1_007_003", 4);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (6, 99, "vo_minigame_1013_icon_2_008_001", 1500, 4, "大所帯ですわね", "マコト班集合！", 11, "vo_minigame_1013_icon_1_008_001", 3);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (6, 99, "vo_minigame_1013_icon_2_008_002", 1500, 4, "エリコ班へようこそ", "連携してくぞ！", 12, "vo_minigame_1013_icon_1_008_002", 3);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (8, 0, "vo_minigame_1013_icon_2_020_001", 3000, 1, "ナナカちゃんに\nお任せあれ", "みんなに力を！", 13, "vo_minigame_1013_icon_1_020_001", 6);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (9, 0, "vo_minigame_1013_icon_2_022_001", 3000, 1, "はっはっは！\n任せろ！", "任せてくれたまえ", 14, "vo_minigame_1013_icon_1_022_001", 7);
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (10, 0, "vo_minigame_1013_icon_2_023_001", 3000, 1, "どんどんいくわよ", "ほな、いきまひょか", 15, "vo_minigame_1013_icon_1_023_001", 8);
